mod common;
mod editor_support;
use serde_json::{Value,json};
use openvector::image_document::ImageDocument;
use openvector::document_controls::DocumentSettings;
use editor_support::{automatic_document,compare_document_state,compare_json,compare_settings,hex};
fn tool(value:&Value)->&'static str{match value.as_i64().unwrap(){0=>"pan",3=>"pencil",4=>"picker",5=>"fill",6=>"zap",7=>"background",_=>panic!("invalid tool")}}
fn point(value:&Value)->[f64;2]{[value[0].as_f64().unwrap(),value[1].as_f64().unwrap()]}
fn compare_frame(document:&ImageDocument,selected:&DocumentSettings,page:&str,expected:&Value,label:&str){
    let background=document.background_state();let native=&expected["visibility"];assert_eq!(background.count as u64,native["header"][3].as_u64().unwrap(),"{label} size");assert_eq!(background.active,native["header"][5].as_u64().unwrap()!=0,"{label} active");
    let hidden:Vec<usize>=native["visible"].as_array().unwrap().iter().enumerate().filter(|(_,v)|!v.as_bool().unwrap_or_else(||v.as_i64().unwrap()!=0)).map(|(i,_)|i).collect();assert_eq!(background.hidden_regions,hidden,"{label} hidden");compare_json(&json!(background.undo),&native["undo"],"background undo");compare_json(&json!(background.redo),&native["redo"],"background redo");
    let editor=document.editing_state().unwrap();assert_eq!(editor.bgra,hex(expected["bgra"].as_str().unwrap()),"{label} editor pixels");assert_eq!(editor.key,expected["key"].as_str().unwrap(),"{label} editor key");let encoded=serde_json::to_value(&editor).unwrap();for name in ["undo","redo"]{let expected=Value::Array(expected[name].as_array().unwrap().iter().map(|r|{let mut r=r.clone();r.as_object_mut().unwrap().remove("bits");r}).collect());compare_json(&encoded[name],&expected,&format!("{label} editor {name}"));}
    assert_eq!(if background.active{background.tool.as_str()}else{editor.tool.as_str()},tool(&expected["inputMode"]),"{label} tool");compare_json(&json!(editor.color),&Value::Array(expected["paintArgb"].as_array().unwrap().iter().rev().cloned().collect()),"paint color");compare_settings(selected,expected["selectedSettingsBits"].as_str().unwrap(),expected["paletteArgbBits"].as_str().unwrap());let page_id=match page{"background"=>15,"editing"=>14,"smoothing"=>16,"export"=>if selected.advanced{17}else{19},_=>panic!("invalid page")};assert_eq!(page_id,native["header"][4].as_i64().unwrap(),"{label} page");assert_eq!(if page=="editing"{1}else{2},native["header"][6].as_i64().unwrap(),"{label} layer");
}
#[test]
fn all_38_native_background_document_sessions(){
    let rows=common::read_ndjson("background-edit-reference.ndjson.gz");assert_eq!(rows.len(),39);let metadata=&rows[0];
    for workflow in &rows[1..]{let label=workflow["id"].as_str().unwrap();let(mut document,automatic)=automatic_document(&workflow["input"]);compare_document_state(&automatic.state,&workflow["expectedAutomatic"]["state"],&metadata["parameters"]);let mut selected=automatic.settings;let mut page="background";let mut completed=0;document.begin_editing().unwrap();document.begin_background_editing().unwrap();compare_frame(&document,&selected,page,&workflow["expectedFrames"][0],label);
        for(index,action)in workflow["actions"].as_array().unwrap().iter().enumerate(){
            if action["action"]==6{let event=json!({"phase":"select","tool":tool(&action["tool"])});if page=="background"{document.background_gesture(&event).unwrap();}else{document.gesture(&event).unwrap();}}
            else if action.get("phase").is_some(){let event=json!({"phase":action["phase"],"point":action["point"],"buttons":action["buttons"],"button":action["button"],"modifiers":action["modifiers"]});if page=="background"{document.background_gesture(&event).unwrap();}else{document.gesture(&event).unwrap();}}
            else{match action["action"].as_i64().unwrap(){
                10=>{document.begin_editing().unwrap();page="editing";},11=>{document.gesture(&json!({"phase":"color","color":action["argb"].as_array().unwrap().iter().rev().collect::<Vec<_>>()})).unwrap();},12=>{document.begin_background_editing().unwrap();page="background";},13=>{document.undo_background();},14=>{document.redo_background();},15=>{document.revert_background();},
                16=>{let state=document.state();let map=state.segmentation.as_ref().unwrap();let region=openvector::vector_output::find_contour_region(map.width as i32,map.height as i32,map.indices.as_ref().unwrap(),state.contours.as_ref().unwrap(),point(&action["point"]));assert_eq!(region,workflow["expectedFrames"][index+1]["queryRegion"].as_i64().unwrap(),"{label} query");},
                18=>{let input=&workflow["additionalInputs"][action["source"].as_str().unwrap()];let decoded=openvector::image_input::decode_image(&common::b64(input["bytes"].as_str().unwrap())).unwrap();let filename=openvector::image_input::resolve_image_filename(input["name"].as_str().unwrap());document.set_source(decoded.width,decoded.height,&decoded.bgra,decoded.has_alpha,filename.shadow_control as f64).unwrap();selected.palette.clear();selected.background_mode=-1;selected.background=[1.0,1.0,1.0,0.0];let mut controls=Value::Object(selected.to_json());controls["extension"]=json!(filename.extension);let replaced=document.run_automatic(&controls).unwrap();selected=replaced.settings;compare_document_state(&replaced.state,&workflow["expectedFrames"][index+1]["replacedSource"]["automatic"]["state"],&metadata["parameters"]);document.begin_editing().unwrap();page="export";},
                19=>{match action["slot"].as_str().unwrap(){"setUseAdvancedMode(bool)"=>selected.advanced=action["value"].as_bool().unwrap_or_else(||action["value"].as_i64().unwrap()!=0),"setAdvContourSmoothness(int)"=>selected.smoothness=action["value"].as_i64().unwrap() as i32,"setAdvCurveComplexity(int)"=>selected.curve_complexity=action["value"].as_i64().unwrap() as i32,other=>panic!("unknown slot {other}")}},
                21=>{document.toggle_background(point(&action["point"])).unwrap();},22=>{let point=if action["kind"]==3{compare_json(&Value::Array(action["coordinates"].as_array().unwrap()[..2].to_vec()),&Value::Array(action["coordinates"].as_array().unwrap()[2..].to_vec()),"raw point producer");point(&action["coordinates"])}else{[action["x"].as_f64().unwrap()+0.5,action["y"].as_f64().unwrap()+0.5]};document.gesture(&json!({"phase":"press","point":point,"buttons":1,"button":1})).unwrap();},2=>{document.undo_edit().unwrap();},3=>{document.redo_edit().unwrap();},4=>{document.revert_edits().unwrap();},
                5|23=>{if page=="editing"{if selected.advanced{document.commit_editing().unwrap();}else{document.finish_editing(&Value::Object(selected.to_json()),None).unwrap();}page=if selected.advanced{"smoothing"}else{"export"};}else if page=="smoothing"{let smooth=document.run_task("smoothing",&Value::Object(selected.to_json()),None).unwrap();let fit=document.run_task("fitting",&Value::Object(selected.to_json()),None).unwrap();if !smooth.did_work&&!fit.did_work{document.begin_background_editing().unwrap();page="background";}}else{document.finish_background_editing();page="export";}compare_document_state(&document.snapshot(),&workflow["expectedCompleted"][completed]["state"],&metadata["parameters"]);completed+=1;},other=>panic!("unknown background action {other}")
            }}compare_frame(&document,&selected,page,&workflow["expectedFrames"][index+1],&format!("{label}/{index}"));
        }assert_eq!(completed,workflow["expectedCompleted"].as_array().unwrap().len());
    }
}
#[test]
fn shared_pointer_updates_before_missing_geometry_error(){
    use openvector::background_editor::BackgroundEditor;use openvector::editor_input::EditorPointer;
    let mut editor=BackgroundEditor::new();assert!(editor.begin().is_err());editor.accept_vectors(4);editor.begin().unwrap();let mut pointer=EditorPointer::default();assert!(editor.gesture(&json!({"phase":"press","point":[-4,3],"buttons":1}),0,0,&[],None,&mut pointer).is_err());assert_eq!(pointer.previous_point,[-4.0,3.0]);let snapshot=editor.snapshot();assert!(editor.gesture(&json!({"phase":"color","color":[0,0,0,1]}),0,0,&[],None,&mut pointer).is_err());assert_eq!(editor.snapshot(),snapshot);assert_eq!(editor.finish().tool,"pan");assert_eq!(editor.revert().count,4);
}
